                   "Idempotency-Key" => SecureRandom.uuid }
    end

    expect(response).to have_http_status(422)
    expect(response.parsed_body).to eq("reason" => "invalid_snapshot")
    expect(TimesheetEntry.unscoped.where(id: [92_001, 92_002])).not_to exist
    expect(company_b.timesheet_entries.where(note: "private note of A")).not_to exist
  end
end

