# Timekeeping admitted entry bodies up to JSON's default 100 levels before it
# capped new bodies lower, and the relay never skips a stored snapshot. The
# receiver must therefore accept the deepest such entry inside its batch.
RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots nesting", type: :request do
  let(:nesting_company) { create(:company) }
  let(:nesting_project) { create(:project, client: create(:client, company: nesting_company)) }
  let(:nesting_user) { create(:user).tap { |user| create(:employment, company: nesting_company, user:) } }

  def nested_metadata(levels)
    levels.times.reduce("leaf") { |value, _| { "child" => value } }
  end

  def nesting_batch(entry_id, proof_metadata)
    entry = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields").index_with(nil).merge(
      "id" => entry_id, "company_id" => nesting_company.id, "version" => 1, "project_id" => nesting_project.id,
      "user_id" => nesting_user.id, "work_date" => "2026-03-02", "duration" => 60.0, "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => proof_metadata, "created_at" => "2026-03-02T09:00:00Z",
      "updated_at" => "2026-03-02T09:00:00Z"
    )
    { "schema_version" => 1,
      "snapshots" => [{ "generation" => TimekeepingOwnership.current.generation, "outbox_position" => 1,
                        "entry" => entry }] }
  end

  def post_nesting_batch(batch)
    with_timekeeping_service_token do |token|
      post "/internal/v1/timekeeping/entry-snapshots", params: JSON.generate(batch, max_nesting: false),
        headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json",
                   "Idempotency-Key" => SecureRandom.uuid }
    end
  end

  it "applies an entry whose body sat at JSON's default limit of 100 levels" do
    # The body is one level, so its metadata held at most 99 nested objects.
    metadata = nested_metadata(99)

    post_nesting_batch(nesting_batch(90_401, metadata))

    expect(response).to have_http_status(:ok)
    expect(TimesheetEntry.find(90_401).proof_metadata).to eq(metadata)
  end

  it "refuses a batch nested deeper than any body Timekeeping could admit, writing nothing" do
    post_nesting_batch(nesting_batch(90_402, nested_metadata(100)))

    expect(response).not_to have_http_status(:ok)
    expect(TimesheetEntry.where(id: 90_402)).to be_empty
  end

  it "stores decimals finer than a Float in both metadata fields exactly, nested objects and arrays included" do
    batch = nesting_batch(90_403, { "rates" => [1, "1.00000000000000000002"] })
    entry = batch.dig("snapshots", 0, "entry")
    entry["source_metadata"] = { "rate" => "1.00000000000000000001" }
    body = JSON.generate(batch).sub('"1.00000000000000000001"', "1.00000000000000000001")
                               .sub('"1.00000000000000000002"', "1.00000000000000000002")

    with_timekeeping_service_token do |token|
      post "/internal/v1/timekeeping/entry-snapshots", params: body,
        headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json",
                   "Idempotency-Key" => SecureRandom.uuid }
    end

    expect(response).to have_http_status(:ok)
    stored = ActiveRecord::Base.connection.select_rows(
      "SELECT source_metadata::text, proof_metadata::text FROM timesheet_entries WHERE id = 90403"
    )
    expect(stored).to eq([['{"rate": 1.00000000000000000001}', '{"rates": [1, 1.00000000000000000002]}']])
  end
end

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots idempotency", type: :request do
  it "returns the first answer for a replayed key and batch and answers idempotency_key_reused for a new batch under that key" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    entry_id = 90_201
    batch = lambda do |version|
      entry = TimekeepingSnapshots.entry(id: entry_id, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: TimekeepingOwnership.current.generation))
    end
    key = SecureRandom.uuid

    with_timekeeping_service_token do |token|
      deliver = lambda do |version|
        post "/internal/v1/timekeeping/entry-snapshots", params: batch.call(version).to_json,
          headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json", "Idempotency-Key" => key }
        [response.status, response.parsed_body]
      end

      # contracts/timekeeping/idempotency.yml: "Same key and body returns the same answer; same key with a new body
      # answers idempotency_key_reused".
      first = deliver.call(1)
      expect(first).to eq([200, { "applied" => 1, "ignored" => 0 }])
      expect(deliver.call(1)).to eq(first)

      expect(deliver.call(2)).to eq([422, { "reason" => "idempotency_key_reused" }])
      expect(TimesheetEntry.find(entry_id).attributes.slice("version", "note")).to eq("version" => 1, "note" => "v1")
    end
  end
end

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots handoff window", type: :request do
  it "answers 409 stale_generation over HTTP for a previous-generation snapshot past P and after the flip, writing nothing" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    entry_id = 90_101

    item = lambda do |version:, generation:, outbox_position:|
      entry = TimekeepingSnapshots.entry(id: entry_id, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.item(entry, generation:, outbox_position:)
    end

    TimekeepingOwnership.current.update!(generation: 2, handoff_step: "freeze", final_outbox_position: 10)

    with_timekeeping_service_token do |token|
      deliver = lambda do |snapshot|
        post "/internal/v1/timekeeping/entry-snapshots",
          params: TimekeepingSnapshots.batch(snapshot).to_json,
          headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json",
                     "Idempotency-Key" => SecureRandom.uuid }
      end

      # "During a handoff, between closing admission and the ownership flip, it also accepts the outgoing
      # owner's previous-generation snapshots, but only up to the final outbox position captured when that
      # owner was frozen."
      deliver.call(item.call(version: 1, generation: 1, outbox_position: 11))
      expect(response).to have_http_status(409)
      expect(response.parsed_body).to eq("reason" => "stale_generation")
      expect(TimesheetEntry.with_discarded.find_by(id: entry_id)).to be_nil

      deliver.call(item.call(version: 1, generation: 1, outbox_position: 10))
      expect(response).to have_http_status(200)
      expect(response.parsed_body).to eq("applied" => 1, "ignored" => 0)

      # "The flip removes that permission."
      TimekeepingOwnership.current.update!(handoff_step: nil)
      deliver.call(item.call(version: 2, generation: 1, outbox_position: 5))
      expect(response).to have_http_status(409)
      expect(response.parsed_body).to eq("reason" => "stale_generation")
      expect(TimesheetEntry.with_discarded.find(entry_id)).to have_attributes(version: 1, note: "v1")
    end
  end
end

# "any `409 stale_generation` outside a handoff;" needs a lasting record of the refusal, because the refused
# batch's transaction rolls back and would otherwise leave no trace for timekeeping:alerts.
RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots stale-generation refusal records", type: :request do
  let(:refusal_company) { create(:company) }
  let(:refusal_project) { create(:project, client: create(:client, company: refusal_company)) }
  let(:refusal_user) { create(:user).tap { |user| create(:employment, company: refusal_company, user:) } }

  def deliver_refusal_snapshot(token, entry_id:, outbox_position: 1)
    entry = TimekeepingSnapshots.entry(id: entry_id, company_id: refusal_company.id, version: 1,
                                       project_id: refusal_project.id, user_id: refusal_user.id)
    post "/internal/v1/timekeeping/entry-snapshots",
      params: TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1, outbox_position:)).to_json,
      headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json",
                 "Idempotency-Key" => SecureRandom.uuid }
  end

  it "records a nil handoff step for a refusal outside a handoff and the freeze step for one refused during it" do
    TimekeepingOwnership.current.update!(generation: 2, handoff_step: nil)

    with_timekeeping_service_token do |token|
      deliver_refusal_snapshot(token, entry_id: 90_701, outbox_position: 5)
      expect([response.status, response.parsed_body]).to eq([409, { "reason" => "stale_generation" }])
      expect(TimekeepingStaleGenerationRefusal.pluck(:company_id, :handoff_step)).to eq([[refusal_company.id, nil]])

      # A refusal during a handoff is recorded with that step, so the alert can leave it out.
      TimekeepingOwnership.current.update!(handoff_step: "freeze", final_outbox_position: 10)
      deliver_refusal_snapshot(token, entry_id: 90_701, outbox_position: 11)
      expect([response.status, response.parsed_body]).to eq([409, { "reason" => "stale_generation" }])
    end

    expect(TimekeepingStaleGenerationRefusal.order(:id).pluck(:company_id, :handoff_step))
      .to eq([[refusal_company.id, nil], [refusal_company.id, "freeze"]])
    expect(TimesheetEntry.with_discarded.find_by(id: 90_701)).to be_nil
  end

  # A refusal made during a handoff must stay marked with that step after the handoff clears, or a
  # reader that looks at the ownership row later would count it as outside a handoff.
  it "keeps the handoff step a refusal saw after the handoff ends, so only the later refusal counts as outside one" do
    TimekeepingOwnership.current.update!(generation: 2, handoff_step: "close_admission")

    with_timekeeping_service_token do |token|
      deliver_refusal_snapshot(token, entry_id: 93_001)
      expect([response.status, response.parsed_body]).to eq([409, { "reason" => "stale_generation" }])

      TimekeepingOwnership.current.update!(handoff_step: nil)
      deliver_refusal_snapshot(token, entry_id: 93_002)
      expect([response.status, response.parsed_body]).to eq([409, { "reason" => "stale_generation" }])
    end

    rows = TimekeepingStaleGenerationRefusal.where(company_id: refusal_company.id).order(:created_at, :id)
    expect(rows.pluck(:handoff_step)).to eq(["close_admission", nil])
  end
end

# Generated by Descant: acceptance tests below.
RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots exact values", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, client: create(:client, company:), billable: false) }
  let(:user) { create(:user) }

  # "unsent_after returns ascending string-keyed rows whose entry holds exactly the contract fields,
  # with microsecond timestamps and exact duration bits"
  # The source keeps the bits only if the receiver does too: the controller parses numbers as
  # BigDecimal, and the duration cast must not round a subnormal to zero on the way into the projection.
  it "stores delivered durations with identical float bits, 5e-324 included, and timestamps with their microseconds" do
    durations = { 93_001 => 5e-324, 93_002 => 0.1 + 0.2, 93_003 => 1.5 }
    items = durations.map do |id, duration|
      entry = TimekeepingSnapshots.entry(id:, company_id: company.id, version: 1, project_id: project.id,
                                         user_id: user.id, duration:,
                                         created_at: "2026-03-02T09:00:00.123456Z",
                                         updated_at: "2026-03-02T09:00:00.654321Z")
      TimekeepingSnapshots.item(entry, generation: TimekeepingOwnership.current.generation, outbox_position: id)
    end
    body = TimekeepingSnapshots.batch(*items).to_json

    with_timekeeping_service_token do |token|
      post "/internal/v1/timekeeping/entry-snapshots", params: body,
        headers: { "CONTENT_TYPE" => "application/json", "Authorization" => "Bearer #{token}",
                   "Idempotency-Key" => SecureRandom.uuid }
    end

    expect(response).to have_http_status(:ok)
    expect(response.parsed_body).to eq("applied" => 3, "ignored" => 0)
    durations.each do |id, duration|
      stored = TimesheetEntry.unscoped.find(id)
      expect([id, [stored.duration].pack("G")]).to eq([id, [duration].pack("G")])
      expect(stored.created_at.utc.iso8601(6)).to eq("2026-03-02T09:00:00.123456Z")
      expect(stored.updated_at.utc.iso8601(6)).to eq("2026-03-02T09:00:00.654321Z")
    end
  end
end
